pub fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let l = s.len();
    let p = l - (l % 3); // largest multiple of 3 not exceeding l

    // Start with an unchanged copy; we will overwrite indices in [0, p)
    let mut res = s.clone();

    // Apply the mapping within each full triplet:
    // (0,1,2) -> (2,0,1), repeated for each group of 3.
    for base in (0..p).step_by(3) {
        res[base] = s[base + 2];
        res[base + 1] = s[base];
        res[base + 2] = s[base + 1];
    }

    res
}

